describe('Modal Scroll Lock', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should prevent page scrolling when modal is open', () => {
    // Get initial scroll position
    cy.window().then((win) => {
      const initialScrollY = win.scrollY;

      // Scroll down to ensure page is scrollable
      cy.scrollTo(0, 500);

      // Open modal
      cy.get('[data-testid="open-modal-btn"]').click();

      // Verify modal is visible
      cy.get('[data-testid="modal"]').should('be.visible');

      // Attempt to scroll
      cy.scrollTo(0, 1000);

      // Verify scroll position hasn't changed significantly
      cy.window().then((win) => {
        expect(win.scrollY).to.equal(500);
      });
    });
  });

  it('should restore page scrolling when modal is closed', () => {
    // Scroll down
    cy.scrollTo(0, 500);

    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    // Close modal
    cy.get('[data-testid="close-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('not.exist');

    // Verify page can scroll again
    cy.scrollTo(0, 1000);
    cy.window().then((win) => {
      expect(win.scrollY).to.be.greaterThan(500);
    });
  });

  it('should prevent scroll on body element when modal is open', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    // Check that body has overflow hidden or similar scroll-lock class
    cy.get('body').should('have.css', 'overflow', 'hidden').or('have.class', 'modal-open');
  });

  it('should handle multiple modal open/close cycles', () => {
    for (let i = 0; i < 3; i++) {
      // Open modal
      cy.get('[data-testid="open-modal-btn"]').click();
      cy.get('[data-testid="modal"]').should('be.visible');

      // Verify scroll is locked
      cy.window().then((win) => {
        expect(win.document.body.style.overflow).to.equal('hidden');
      });

      // Close modal
      cy.get('[data-testid="close-modal-btn"]').click();
      cy.get('[data-testid="modal"]').should('not.exist');

      // Verify scroll is restored
      cy.window().then((win) => {
        expect(win.document.body.style.overflow).to.not.equal('hidden');
      });
    }
  });
});
